import{z as l,x as A,o as e,c as s,q as r,j as n,D as E,d as o,s as i,S as B}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"对手方分层与定向","description":"","frontmatter":{"title":"对手方分层与定向","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/mm-counterparty-tiering.md","filePath":"quant/mm-counterparty-tiering.md","lastUpdated":1791063341000}'),m={name:"quant/mm-counterparty-tiering.md"};function p(d,a,u,h,c,_){const t=A("Mermaid");return e(),s("div",null,[a[2]||(a[2]=r('<h1 id="对手方分层与定向" tabindex="-1">对手方分层与定向 <a class="header-anchor" href="#对手方分层与定向" aria-label="Permalink to &quot;对手方分层与定向&quot;">​</a></h1><div class="epigraph"><p>把知情概率当成全市场一个常数，价差就按最毒的对手收；低毒流被高价赶走，剩下的池子更毒——分层定价不是歧视，是让做市可活的条件。</p><footer>—— 据 Glosten and Milgrom, Journal of Financial Economics, 1985；Harris, Trading and Exchanges, 2003 整理</footer></div><p><a href="/quant/mm-hedging-inventory">上一课</a>把库存风险转移给对冲腿之后，对手仍被当成一个整体在定价。<a href="/quant/glosten-milgrom">Glosten–Milgrom</a> 的知情者比例 \\(\\mu\\) 是单一参数：所有人同样可能知情。真实流不是：小额零售、机构母单与程序化单混在同一簿里，被同一个价差收费。本课把 \\(\\mu\\) 截面化：用什么特征识别对手、对每层报什么价、哪些做法越线。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>混合定价的均衡是逆选择螺旋：价差按平均毒性收，价差越宽，对成本敏感的低毒流越先离开，剩余池子的平均毒性越高，价差再宽——驱逐直到市场只剩知情者与被动指数流。缺口因此是三层：识别（用什么可观测特征分层）、定价（对每层报什么价与量）、合规（差别化与抢先的边界在哪）。不做分层的做市商最终只能收全市场最宽的价差，或在消息日历上停摆，把成交量让给会分层的人。</p>',5)),(e(),n(B,null,{default:E(()=>[i(t,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20MIX%5B%22%E6%B7%B7%E5%90%88%E6%B5%81%EF%BC%9A%E7%9F%A5%E6%83%85%E4%B8%8E%E4%BD%8E%E6%AF%92%E6%B7%B7%E5%9C%A8%E4%B8%80%E8%B5%B7%22%5D%20--%3E%20AVG%5B%22%E4%BB%B7%E5%B7%AE%E6%8C%89%E5%B9%B3%E5%9D%87%E6%AF%92%E6%80%A7%E6%94%B6%E5%8F%96%22%5D%0A%20%20AVG%20--%3E%20LEAVE%5B%22%E6%88%90%E6%9C%AC%E6%95%8F%E6%84%9F%E7%9A%84%E4%BD%8E%E6%AF%92%E6%B5%81%E7%A6%BB%E5%BC%80%22%5D%0A%20%20LEAVE%20--%3E%20WORSE%5B%22%E5%89%A9%E4%BD%99%E6%B1%A0%E5%AD%90%E5%B9%B3%E5%9D%87%E6%AF%92%E6%80%A7%E5%8D%87%E9%AB%98%22%5D%0A%20%20WORSE%20--%3E%20WIDE%5B%22%E4%BB%B7%E5%B7%AE%E8%A2%AB%E8%BF%AB%E5%86%8D%E6%94%B6%E5%AE%BD%22%5D%0A%20%20WIDE%20--%3E%20LEAVE%0A%20%20WIDE%20--%3E%20END%5B%22%E5%9D%87%E8%A1%A1%EF%BC%9A%E5%8F%AA%E5%89%A9%E7%9F%A5%E6%83%85%E8%80%85%E4%B8%8E%E8%A2%AB%E5%8A%A8%E6%8C%87%E6%95%B0%E6%B5%81%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p><span class="marginnote">直觉类比：保险公司分不清好坏司机时，只能按平均事故率收保费；好司机觉得亏，转投别家，剩下的池子事故率更高，保费再涨——这就是「柠檬市场」螺旋。做市商不分层定价时面对的是同一道题，只是「保费」是价差。</span></p><h3 id="特征族与打分" tabindex="-1">特征族与打分 <a class="header-anchor" href="#特征族与打分" aria-label="Permalink to &quot;特征族与打分&quot;">​</a></h3><p>分层特征三类：身份与路由属性（账户类型、订单标记、进入场所）、订单形态（大小、是否拆分、方向与公开消息的时序相关）、历史行为（该来源成交后固定窗口内中点朝成交方向的位移，即 markout 得分）。打分的会计口径直接用<a href="/quant/adverse-selection-cost">逆向选择成本度量</a>：每层分别算有效价差减实现价差，谁在事后吃掉你的价差，数字自己会排出来。零售流的行为差异有大样本证据，见 <a href="/quant/boehmer-retail-flow">零售流的证据</a> 一类研究。</p><p><span class="marginnote">术语翻译：markout 就是「成交后过一小段时间，中点朝成交方向走了多少」。你买入后价格继续涨，说明你更可能是知情方，对手方（做市商）的 markout 为负——瞬间赚了价差，几分钟后在更好的价位把库存亏回去。逐来源累积这个数，就是最朴素的毒性档案。</span></p><p><span class="marginnote">markout 得分的窗口必须固定并写进台账：把窗口从 30 秒改成 5 分钟，「同一来源」的毒性排序可能翻转。窗口选择本身就是一层模型假设，前台与风控各用各的窗口，分层阈值就永远吵不完。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>动作按层配套：对低分来源收窄价差、扩大规模，甚至内部化对敲（自己接下对手单，不出现在公开簿）；对高分来源加宽、缩量、拒单，或改走询价——定向报价把「挂给所有人」改成「报给特定对手」，价格可以带该对手的毒性条件。分层经济等价于把单一市场拆成多个子市场，每个子市场的 \\(\\mu\\) 更低、价差更窄，公开簿反而更健康。</p><p><a href="/quant/pin">PIN</a> 的日度似然给不出逐笔分层，但它是分层有效性的低频校验：你的分层是否真的把高 PIN 时段的高毒来源挑了出来。</p><p><span class="marginnote">数字实例：假设全池混合的知情概率对应 12 分宽的价差。分层后，低毒层按 \\(\\mu\\approx 0.05\\) 收 4 分、高毒层按 \\(\\mu\\approx 0.5\\) 收 20 分——低毒层价差缩小三分之二，被窄价差吸引回流，公开簿的总流量与深度反而变厚。分层不是把蛋糕切小，是把被高价赶走的流量请回来。</span></p>',9)),(e(),n(B,null,{default:E(()=>[i(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20FLOW%5B%22%E8%AE%A2%E5%8D%95%E6%B5%81%E8%BF%9B%E5%85%A5%22%5D%20--%3E%20FEAT%5B%22%E7%89%B9%E5%BE%81%EF%BC%9A%E8%BA%AB%E4%BB%BD%E3%80%81%E5%BD%A2%E6%80%81%E3%80%81markout%22%5D%0A%20%20FEAT%20--%3E%20TIER%5B%22%E6%AF%92%E6%80%A7%E5%88%86%E5%B1%82%E6%89%93%E5%88%86%22%5D%0A%20%20TIER%20--%3E%20LOW%5B%22%E4%BD%8E%E6%AF%92%E5%B1%82%EF%BC%9A%E7%AA%84%E4%BB%B7%E5%B7%AE%E3%80%81%E5%A4%A7%E9%A2%9D%E3%80%81%E5%86%85%E9%83%A8%E5%8C%96%22%5D%0A%20%20TIER%20--%3E%20HIGH%5B%22%E9%AB%98%E6%AF%92%E5%B1%82%EF%BC%9A%E5%AE%BD%E4%BB%B7%E5%B7%AE%E3%80%81%E7%BC%A9%E9%87%8F%E3%80%81RFQ%22%5D%0A%20%20LOW%20--%3E%20ACCT%5B%22%E9%80%90%E5%B1%82%E6%9C%89%E6%95%88%E4%BB%B7%E5%B7%AE%E5%87%8F%E5%AE%9E%E7%8E%B0%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20HIGH%20--%3E%20ACCT%0A%20%20ACCT%20--%3E%7C%22%E5%9B%9E%E5%86%99%E9%98%88%E5%80%BC%22%7C%20TIER%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分层改变的是价差对谁收：Glosten–Milgrom 里价差是条件期望之差，条件集合从「全市场」换成「这一层」，价差就跟着这一层的 \\(\\mu\\) 走。内部化低毒流的经济学不是掠夺而是分离均衡：愿意被内部化的对手拿到更窄的价差，公开簿剩余池子的毒性被明码标价。定向报价更进一步：报价本身成为对特定对手的条件合同，做市商从「被动接所有来者」变成「选择与谁成交」。</p><p>反馈环要闭到阈值：分层的正确性只有会计能检验——某层开始持续吃掉实现价差，阈值就该移动；某层长期贡献价差收入，规模就该放开。这是第一课「模型是分解器」口径在对手维度的重演。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>红线在信息流：不能把一层对手的成交信息用于对另一层的抢先报价——front-running 与信息屏障是监管与合同的双重对象。不能对同层对手做无依据的差别定价，标记错误会让受保护人群系统性拿到劣价。小来源样本不足，阈值要平滑回退到全池价差，不要让两个 markout 样本决定一个价差。分层是风险管理语言：本课不提供识别具体自然人对手或定向淘汰对手的构造。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>单一 \\(\\mu\\) 按平均毒性收费，引发逆选择螺旋；分层是让低毒流留在市场的条件。</li><li>特征三类：身份路由、订单形态、历史 markout；会计口径是逐层有效价差减实现价差。</li><li>动作按层配套：窄价差与内部化给低毒层，宽价差、缩量与 RFQ 给高毒层。</li><li>定向报价把报价变成对特定对手的条件合同，等价于拆分子市场。</li><li>阈值靠会计反馈闭环；窗口与规则进台账。</li><li>信息屏障与公平对待是红线；小来源回退全池价差。</li><li>出处：Glosten and Milgrom, <em>Journal of Financial Economics</em>, 1985；Easley, Kiefer, O&#39;Hara and Paperman, <em>Journal of Finance</em>, 1996；Harris, <em>Trading and Exchanges</em>, 2003。</li></ul>',7))])}const T=l(m,[["render",p]]);export{f as __pageData,T as default};
